function simplifySchema(schema) {
  const out = {};
  if (schema.type !== undefined) out.type = schema.type;
  if (schema.enum !== undefined) out.enum = schema.enum;
  if (schema.required !== undefined) out.required = schema.required;
  if (schema.additionalProperties !== undefined) out.additionalProperties = schema.additionalProperties;
  if (schema.properties) {
    out.properties = {};
    for (const fieldName of Object.keys(schema.properties)) {
      out.properties[fieldName] = simplifySchema(schema.properties[fieldName]);
    }
  }
  if (schema.items) out.items = simplifySchema(schema.items);
  return out;
}

// 1. Pick the category's rules and schema
const e = $json;
const rules = CATEGORY_RULES[e.category];
const schema = SCHEMAS[e.category];
if (!rules || !schema) {
  throw new Error('No extraction setup for category: ' + e.category);
}

// 2. Random marker (8 hex characters), same method as in Build Prompt
function makeMarker() {
  const bytes = new Uint8Array(4);
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    crypto.getRandomValues(bytes);
  } else {
    for (let i = 0; i < bytes.length; i++) {
      bytes[i] = Math.floor(Math.random() * 256);
    }
  }
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
}

const parts = [e.sender_email, e.sender_name, e.subject, e.body];
let marker = makeMarker();
let tries = 0;
while (parts.some(p => String(p || '').includes(marker))) {
  tries++;
  if (tries >= 5) {
    throw new Error('Could not generate a marker that is absent from the email');
  }
  marker = makeMarker();
}

// 3. Build the messages
const systemPrompt = BASE
  .replaceAll('{{CATEGORY_RULES}}', rules)
  .replaceAll('{{MARKER}}', marker);

const userMessage =
  `<<<EMAIL_${marker}>>>\n` +
  `From: ${e.sender_name || ''} <${e.sender_email}>\n` +
  `Subject: ${e.subject || '(no subject)'}\n` +
  `Received: ${e.received_local}\n` +
  `Body truncated: ${e.body_truncated ? 'yes' : 'no'}\n` +
  `Body:\n${e.body}\n` +
  `<<<END_${marker}>>>`;

const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: userMessage }
];

// 4. Build the full request for the HTTP node
const requestBody = { model: $env.LLM_MODEL, messages: messages };
if (SEND_SCHEMA_TO_API) {
  requestBody.response_format = {
    type: 'json_schema',
    json_schema: { name: e.category, strict: true, schema: simplifySchema(schema) }
  };
}

return {
  json: {
    run_id: e.run_id,
    message_id: e.message_id,
    category: e.category,
    sender_email: e.sender_email,
    messages: messages,
    request_body: requestBody,
    schema: schema
  }
};

// Validate Extraction: parses the model's answer and checks it against the
// schema carried along from "Build Extraction Request". Works for every category.

const TEST_FAKE_OUTPUT = null;   // for testing only: put a fake answer text here

const ctx = $('Build Extraction Request').item.json;
const schema = ctx.schema;

// The only schema keywords this checker understands
const KNOWN = ['type', 'properties', 'required', 'additionalProperties', 'enum',
               'minimum', 'maximum', 'minLength', 'maxLength', 'pattern',
               'items', 'minItems', 'maxItems'];

const errors = [];
function addError(path, message) {
  if (errors.length < 10) {
    errors.push((path + ': ' + message).slice(0, 150));
  }
}

function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return Number.isInteger(v) ? 'integer' : 'number';
  return typeof v;
}

function typeMatches(v, allowed) {
  const actual = typeOf(v);
  return allowed.some(t => t === actual || (t === 'number' && actual === 'integer'));
}

function check(value, rule, path) {
  for (const key of Object.keys(rule)) {
    if (!KNOWN.includes(key)) {
      throw new Error('Validator does not support schema keyword: ' + key);
    }
  }

  if (rule.type !== undefined) {
    const allowed = Array.isArray(rule.type) ? rule.type : [rule.type];
    if (!typeMatches(value, allowed)) {
      addError(path, 'expected ' + allowed.join(' or ') + ', got ' + typeOf(value));
      return;
    }
  }

  if (rule.enum !== undefined && !rule.enum.includes(value)) {
    addError(path, 'value is not one of the allowed values');
  }

  if (typeof value === 'number') {
    if (rule.minimum !== undefined && value < rule.minimum) {
      addError(path, 'must be at least ' + rule.minimum);
    }
    if (rule.maximum !== undefined && value > rule.maximum) {
      addError(path, 'must be at most ' + rule.maximum);
    }
  }

  if (typeof value === 'string') {
    if (rule.minLength !== undefined && value.length < rule.minLength) {
      addError(path, 'text is too short (minimum ' + rule.minLength + ')');
    }
    if (rule.maxLength !== undefined && value.length > rule.maxLength) {
      addError(path, 'text is too long (maximum ' + rule.maxLength + ')');
    }
    if (rule.pattern !== undefined && !new RegExp(rule.pattern).test(value)) {
      addError(path, 'text does not have the required format');
    }
  }

  if (Array.isArray(value)) {
    if (rule.minItems !== undefined && value.length < rule.minItems) {
      addError(path, 'needs at least ' + rule.minItems + ' items');
    }
    if (rule.maxItems !== undefined && value.length > rule.maxItems) {
      addError(path, 'has more than ' + rule.maxItems + ' items');
    }
    if (rule.items !== undefined) {
      value.forEach((item, i) => check(item, rule.items, path + '[' + i + ']'));
    }
  }

  if (typeOf(value) === 'object') {
    const props = rule.properties || {};
    for (const key of (rule.required || [])) {
      if (!Object.prototype.hasOwnProperty.call(value, key)) {
        addError(path === '' ? key : path + '.' + key, 'missing required field');
      }
    }
    for (const key of Object.keys(props)) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        check(value[key], props[key], path === '' ? key : path + '.' + key);
      }
    }
    if (rule.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!Object.prototype.hasOwnProperty.call(props, key)) {
          addError(path === '' ? '(root)' : path, 'unexpected field: ' + String(key).slice(0, 30));
        }
      }
    }
  }
}

// The model's answer text
const raw = TEST_FAKE_OUTPUT !== null
  ? TEST_FAKE_OUTPUT
  : $json.choices?.[0]?.message?.content;

// Token usage: output = total - prompt, so hidden thinking tokens are counted
const usage = $json.usage || {};
const promptTokens = Number(usage.prompt_tokens) || 0;
const totalTokens = Number(usage.total_tokens) || 0;
const inputTokens = promptTokens;
const outputTokens = totalTokens > promptTokens
  ? totalTokens - promptTokens
  : (Number(usage.completion_tokens) || 0);

// Parse, then validate
let parsed = null;
if (typeof raw !== 'string' || raw.trim() === '') {
  addError('(root)', 'the response was empty');
} else {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    addError('(root)', 'the response was not valid JSON');
  }
}
if (errors.length === 0) {
  check(parsed, schema, '');
}

const valid = errors.length === 0;

return {
  json: {
    run_id: ctx.run_id,
    message_id: ctx.message_id,
    category: ctx.category,
    sender_email: ctx.sender_email,
    valid: valid,
    errors: errors,
    extracted: valid ? parsed : null,
    raw_content: typeof raw === 'string' ? raw.slice(0, 2000) : null,
    input_tokens: inputTokens,
    output_tokens: outputTokens
  }
};

// Decide Extraction Status: picks the new status and calculates the cost of this call.

function readNumberSetting(name) {
  const text = String($env[name] ?? '').trim();
  const value = Number(text);
  if (text === '' || !Number.isFinite(value) || value < 0) {
    throw new Error('Setting ' + name + ' is missing or not a valid number');
  }
  return value;
}

const priceIn = readNumberSetting('LLM_PRICE_INPUT_PER_1M');
const priceOut = readNumberSetting('LLM_PRICE_OUTPUT_PER_1M');

const v = $json;

const status = v.valid ? 'classified' : 'needs_review';
const errorMessage = v.valid
  ? null
  : ('Extraction failed validation: ' + v.errors.join(' | ')).slice(0, 500);

const cost = (v.input_tokens * priceIn + v.output_tokens * priceOut) / 1000000;

return {
  json: {
    ...v,
    status: status,
    error_message: errorMessage,
    extracted_json: v.valid ? JSON.stringify(v.extracted) : null,
    cost_usd: Math.round(cost * 1000000) / 1000000
  }
};

// Prepare Lookup: which email address to search for in Odoo.
// Always the SENDER address, never an address claimed inside the message.
const d = $('Decide Extraction Status').item.json;
const email = String(d.sender_email || '').trim().toLowerCase();
const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
return { json: { run_id: d.run_id, category: d.category, lookup_email: ok ? email : '' } };

// Build Proposal: deterministic code, no LLM. Builds the exact Odoo action the human will approve.
// Mode: Run Once for ALL Items. Every email is handled on its own, and each one is matched
// to its own data by run_id, so several emails in one run can never mix their contacts.

const decidedAll = $('Decide Extraction Status').all().map(i => i.json);
const inputsAll = $('When Executed by Another Workflow').all().map(i => i.json);
const lookupsAll = $('Prepare Lookup').all().map(i => i.json);
const partnersAll = $('Find Partner').all().map(i => i.json).filter(j => j && j.id !== undefined);

// ---- helpers ----
const EMAIL_OK = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function short(text, max) {
  const t = String(text ?? '').replace(/\s+/g, ' ').trim();
  return t.length > max ? t.slice(0, max - 1) + '…' : t;
}
function esc(text) {
  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function clean(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v !== null && v !== undefined && v !== '') out[k] = v;
  }
  return out;
}

// ---- allowlist: the only models, methods and fields an approved action may use ----
const ALLOWED = {
  'crm.lead': {
    methods: ['create'],
    fields: ['name', 'type', 'contact_name', 'partner_name', 'email_from', 'phone', 'description', 'partner_id']
  }
};
function assertAllowed(steps) {
  for (const s of steps) {
    const rule = ALLOWED[s.model];
    if (!rule || !rule.methods.includes(s.method)) {
      throw new Error('Action not allowed: ' + s.model + '.' + s.method);
    }
    for (const key of Object.keys(s.vals)) {
      if (!rule.fields.includes(key)) {
        throw new Error('Field not allowed: ' + s.model + '.' + key);
      }
    }
  }
}

// ---- builds the proposal for ONE email ----
function buildProposal(d, input, lookup, matches) {
  const ex = d.extracted;
  const flags = [];

  const BUILDERS = {
    new_inquiry() {
      const senderEmail = String(d.sender_email || '').toLowerCase();
      let contactEmail = String(ex.email || senderEmail).trim().toLowerCase();
      if (ex.email && contactEmail !== senderEmail) {
        flags.push('The email address in the message (' + short(ex.email, 60) + ') differs from the sender address.');
      }
      if (!EMAIL_OK.test(contactEmail)) {
        flags.push('No valid email address found for the contact.');
        contactEmail = '';
      }

      let partnerId = null;
      let partnerNote;
      if (matches.length === 1) {
        partnerId = matches[0].id;
        partnerNote = 'Linked to existing contact "' + short(matches[0].name, 60) + '" (id ' + partnerId + ').';
      } else if (matches.length > 1) {
        flags.push(matches.length + ' existing contacts share the sender address; none was linked.');
        partnerNote = 'Not linked to any contact (ambiguous).';
      } else {
        partnerNote = 'No existing contact found. The lead keeps the contact details and no contact is created.';
      }

      const who = ex.company || ex.name || contactEmail || 'Unknown sender';
      const description =
        '<p>' + esc(ex.request_summary) + '</p>' +
        (ex.budget_if_mentioned ? '<p><b>Budget mentioned:</b> ' + esc(ex.budget_if_mentioned) + '</p>' : '') +
        '<p><i>Created by InboxOps from the email "' + esc(short(input.subject, 120)) + '" (run ' + d.run_id + ').</i></p>';

      const vals = clean({
        name: short(who + ': ' + ex.request_summary, 120),
        type: 'opportunity',
        contact_name: ex.name,
        partner_name: ex.company,
        email_from: contactEmail,
        phone: ex.phone,
        description: description,
        partner_id: partnerId
      });

      return {
        title: 'Create CRM opportunity',
        steps: [{ ref: 'lead', model: 'crm.lead', method: 'create', vals: vals }],
        lines: [
          'Name: ' + (ex.name || '(not mentioned)'),
          'Email: ' + (contactEmail || '(not mentioned)'),
          'Company: ' + (ex.company || '(not mentioned)'),
          'Phone: ' + (ex.phone || '(not mentioned)'),
          'Request: ' + ex.request_summary,
          'Budget: ' + (ex.budget_if_mentioned || '(not mentioned)'),
          partnerNote
        ]
      };
    }
  };

  let status = 'classified';
  let errorMessage = null;
  let built = null;
  if (BUILDERS[d.category]) {
    built = BUILDERS[d.category]();
    assertAllowed(built.steps);
  } else {
    status = 'needs_review';
    errorMessage = 'No proposal builder for category ' + d.category + ' yet';
  }

  const proposal = {
    version: 1,
    run_id: d.run_id,
    category: d.category,
    title: built ? built.title : 'No action proposed',
    flags: flags,
    steps: built ? built.steps : [],
    details: built ? built.lines : [],
    sender: { name: short(input.sender_name, 100), email: d.sender_email },
    subject: short(input.subject, 200),
    snippet: short(input.body, 400),
    lookup: { email: lookup.lookup_email, matches: matches.map(m => ({ id: m.id, name: short(m.name, 80) })) }
  };

  return {
    run_id: d.run_id,
    status: status,
    error_message: errorMessage,
    proposal_json: JSON.stringify(proposal)
  };
}

// ---- one result per email ----
return lookupsAll.map(lk => {
  const d = decidedAll.find(x => String(x.run_id) === String(lk.run_id));
  const input = inputsAll.find(x => String(x.run_id) === String(lk.run_id));
  if (!d || !input) {
    throw new Error('Data not found for run ' + lk.run_id);
  }
  const matches = lk.lookup_email
    ? partnersAll.filter(p => String(p.email || '').trim().toLowerCase() === lk.lookup_email)
    : [];
  return { json: buildProposal(d, input, lk, matches) };
});
